```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# ROOT
#################################################################

ea:EducationalConcept a owl:Class ;
  rdfs:label "Educational Concept" .

#################################################################
# TOP-LEVEL: ASSESSMENT / TEST
#################################################################

ea:Assessment a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  rdfs:label "Assessment" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Assessment is often used interchangeably with the term test but is not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "exam" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification. Most tests can be classified on multiple, independent categories simultaneously (e.g. a test can be both standardized and high-stakes); therefore the axis-based test subtypes below are NOT asserted disjoint with one another." .

ea:Examination a owl:Class ;
  owl:equivalentClass ea:Test ;
  rdfs:label "Examination" ;
  skos:altLabel "exam", "test" .

#################################################################
# GRANULARITY AXIS
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel ;
  rdfs:label "has granularity" .

ea:GranularityLevel a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept .

ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

#################################################################
# PURPOSE AXIS  (Placement / Formative / Summative / Diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory ;
  rdfs:label "has purpose" .

ea:PurposeCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) ;
  rdfs:comment "Corpus lists placement, formative, summative, and diagnostic as four coordinate categories ('(1) Placement ... (2) Formative ... (3) Summative ... (4) Diagnostic'). Elsewhere the corpus states assessment is 'often divided into initial, formative, and summative categories' (only three), creating tension with the four-way partition asserted here." .

ea:PlacementAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  rdfs:comment "Used to place students according to prior achievement or level of knowledge at the most appropriate point in an instructional sequence. Generally not graded." .

ea:FormativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment",
                "formative evaluation", "formative feedback" ;
  rdfs:comment "Carried out throughout a course to modify teaching and learning; generally low-stakes and often ungraded." .

ea:SummativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  rdfs:comment "Carried out at the end of a course or project to assign a grade; typically high-stakes." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "diagnostic testing" ;
  rdfs:comment "Focuses on the whole of difficulties occurring during the learning process." .

ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: corpus also states 'a common form of formative assessment is diagnostic assessment', subordinating Diagnostic under Formative, in contradiction with the four-way coordinate partition of PurposeCategory above." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
#################################################################

ea:hasPerformanceFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceFormatCategory .

ea:PerformanceFormatCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatValue a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceFormatValue ) .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance assessment" ;
  rdfs:comment "Focuses on achievement; a well-defined task is identified and students create, produce, or do something, often involving real-world application. Performance formats are classified into products and performances." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment .

ea:AuthenticAssessment owl:equivalentClass ea:PerformanceBasedAssessment ;
  rdfs:comment "TENSION: one passage ('Performance assessments may also be called authentic assessments') treats these as synonyms (encoded here via equivalentClass), while another passage ('Assessment types include: ... Performance-based assessments ... Authentic assessment') lists them as separate, coordinate named assessment types." .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; will often include some form of formative assessment." .

#################################################################
# RESPONSE TYPE AXIS (Objective / Subjective)
#################################################################

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ResponseTypeCategory .

ea:ResponseTypeCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:ObjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:ResponseTypeCategory owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

#################################################################
# REFERENCING AXIS (Criterion / Norm / Ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Candidates are measured against defined, objective criteria (e.g. a driving test)." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "normative assessment", "grading on the curve" ;
  rdfs:comment "Not measured against defined criteria; relative to the student body taking it (e.g. an IQ test)." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:NormGroup a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  skos:altLabel "norming group" ;
  rdfs:comment "A sample drawn from a predefined population against which a test taker's position is estimated." .

ea:hasNormGroup a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:NormReferencedTest ;
  rdfs:range ea:NormGroup .

#################################################################
# FORMALITY AXIS (Formal / Informal)
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:FormalFormality a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalFormality a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalFormality ea:InformalFormality ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalFormality ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Usually implies a written document, such as a test, quiz, or paper, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalFormality ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Occurs more casually and does not contribute to a student's final grade." .

#################################################################
# ADMINISTRATION SOURCE AXIS (Internal / External)
#################################################################

ea:hasAdministrationSource a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AdministrationSourceCategory .

ea:AdministrationSourceCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:InternalSource a owl:Class ; rdfs:subClassOf ea:AdministrationSourceCategory .
ea:ExternalSource a owl:Class ; rdfs:subClassOf ea:AdministrationSourceCategory .
ea:AdministrationSourceCategory owl:disjointUnionOf ( ea:InternalSource ea:ExternalSource ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationSource ; owl:someValuesFrom ea:InternalSource ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationSource ; owl:someValuesFrom ea:ExternalSource ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Set by a governing body and marked by unbiased personnel." .

#################################################################
# STANDARDIZATION AXIS (on Test)
#################################################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:subClassOf ea:Test ;
  skos:altLabel "standardized assessment" ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "Flexible in scope and format, and variable in difficulty." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Backward-looking: measures knowledge/skills students learned or academic progress made." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest, ea:ForwardLookingAssessment ;
  rdfs:comment "Forward-looking: attempts to predict a student's ability to succeed in a future endeavor." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                ea:InternationalComparisonTest ea:PsychologicalTest ) .

#################################################################
# STAKES AXIS (High / Low, on Test)
#################################################################

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "A test with important consequences for the individual test taker or institution." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] ;
  rdfs:subClassOf ea:Test .

#################################################################
# SCORE INTERPRETATION AXIS (Norm-referenced / Criterion-referenced test)
#################################################################

ea:hasScoreInterpretation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:ScoreInterpretationCategory .

ea:ScoreInterpretationCategory a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:NormReferencedInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretationCategory .
ea:CriterionReferencedInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretationCategory .
ea:ScoreInterpretationCategory owl:disjointUnionOf
  ( ea:NormReferencedInterpretation ea:CriterionReferencedInterpretation ) ;
  rdfs:comment "'There are two types of test score interpretations: a norm-referenced score interpretation or a criterion-referenced score interpretation.'" .

ea:NormReferencedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasScoreInterpretation ; owl:someValuesFrom ea:NormReferencedInterpretation ] ) ] ;
  rdfs:subClassOf ea:Test ;
  skos:altLabel "NRT" ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

ea:CriterionReferencedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasScoreInterpretation ; owl:someValuesFrom ea:CriterionReferencedInterpretation ] ) ] ;
  rdfs:subClassOf ea:Test ;
  skos:altLabel "CRT" ;
  rdfs:comment "Measures student performance against a fixed set of criteria or learning standards." .

ea:StandardsBasedAssessment a owl:Class ;
  owl:equivalentClass ea:CriterionReferencedTest ;
  rdfs:comment "'Criterion-referenced tests have also been called standards-based assessments.'" .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ;
  rdfs:range xsd:decimal .

ea:MasteryTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:CriterionReferencedTest
    [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test that uses a cutscore: the examinee passes if their score exceeds the cutscore." .

ea:hasPercentileRank a owl:DatatypeProperty ;
  rdfs:domain ea:NormReferencedTest ;
  rdfs:range xsd:decimal .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:NormReferencedTest, ea:HighStakesTest ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

#################################################################
# OTHER NAMED ASSESSMENT TYPES (non-disjoint enumeration)
#################################################################

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "benchmark assessment" .
ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
ea:PortfolioBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "portfolio assessment" .
ea:PreAssessment a owl:Class ;
  owl:equivalentClass ea:PlacementAssessment .

ea:Portfolio a owl:Class ; rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "A compilation of academic work and other educational evidence." .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .

#################################################################
# EXAM / QUIZ FAMILY
#################################################################

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; usually a formative assessment." .

ea:MidtermExam a owl:Class ;
  rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
  rdfs:comment "An exam given near the middle of a grading term. Listed as an example of summative assessment, though another passage calls midterms 'a type of formative or summative assessment' (tension)." .

ea:FinalExam a owl:Class ;
  rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
  rdfs:comment "A final review and assessment of topics covered, typically at course end." .

ea:WrittenTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "A test administered on paper or on a computer." .

#################################################################
# TEST ITEMS
#################################################################

ea:TestItem a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "A component part of a test; the more general term for what is colloquially called a 'question'." .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test .

ea:ItemStem a owl:Class ; rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "The opening of a multiple-choice item: a problem, question, or incomplete statement." .

ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:ItemStem .

ea:AnswerOption a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:AnswerOption owl:disjointUnionOf ( ea:Key ea:Distractor ) .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption .

### Objective / Subjective questions (item-level axis)

ea:ObjectiveQuestion a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveQuestion a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:TestItem-ResponseSplit a owl:Class . # helper not used further

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveQuestion ea:SubjectiveQuestion ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .
ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveQuestion ;
  skos:altLabel "MCQ", "objective response" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasOption ; owl:onClass ea:Key ;
      owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "Consists of a stem and alternatives; only one answer may be keyed as correct." .
ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveQuestion ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasOption ; owl:onClass ea:Key ;
      owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion .
ea:EssayItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveQuestion ;
  skos:altLabel "free response question", "FRQ", "essay question" .

[] a owl:AllDisjointClasses ; owl:members ( ea:ExtendedResponseItem ea:EssayItem ) .

### Two families of multiple-choice questions (tension with sibling list above)

ea:TrueFalseFamilyItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem .
ea:OneBestAnswerFamilyItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem .
ea:MultipleChoiceItem owl:disjointUnionOf ( ea:TrueFalseFamilyItem ea:OneBestAnswerFamilyItem ) ;
  rdfs:comment "TENSION: corpus states 'there are two families of multiple-choice questions ... True/False ... One-Best-Answer', subordinating True/False under MultipleChoiceItem, while elsewhere TrueFalseItem is modeled as a coordinate sibling of MultipleChoiceItem (disjoint objective question types)." .

ea:FillInTheBlankItem a owl:Class ;
  rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides identifying characteristics and requires recall of the correct term." .

ea:hasWordBank a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:FillInTheBlankItem ;
  rdfs:range xsd:boolean .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:MathQuestion a owl:Class ;
  rdfs:subClassOf ea:TestItem ;
  owl:disjointWith ea:ObjectiveQuestion ;
  owl:disjointWith ea:SubjectiveQuestion ;
  rdfs:comment "'Most mathematics questions ... employ a style which does not fall into any of the above categories.'" .

ea:PerformanceTest a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "work sample" ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it." .

ea:SimulationTest a owl:Class ;
  rdfs:subClassOf ea:PerformanceTest ;
  rdfs:comment "Some performance tests are simulations." .

ea:ItemBank a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "Items are stored in an item bank." .

#################################################################
# RUBRICS AND GRADING
#################################################################

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Rubric .

ea:Rubric a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ;
  rdfs:comment "'Rubrics can be classified as holistic, analytic, or developmental' (coordinate partition asserted here)." .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: 'Developmental rubrics, a subset of analytical rubrics' subordinates DevelopmentalRubric under AnalyticRubric, conflicting with the disjoint three-way partition above." .

ea:GradingApproach a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Trains raters to score to a rubric/checklist; comes close to analytic scoring methods but remains holistic at heart." .

#################################################################
# VALIDITY
#################################################################

ea:ValidityEvidence a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "The degree to which evidence and theory support the interpretation of test scores." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                ea:ConsequentialValidity ea:FaceValidity ) ;
  rdfs:comment "Corpus: 'Validity ... is generally gauged through examination of evidence in the following categories: Content validity, Criterion validity, Construct validity. Others are: consequential validity, face validity' (coordinate siblings)." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: 'Construct validity ... subsumes all other types of validity' and 'construct validity is not distinct from the support for the substantive theory' implies Construct validity is the overarching superclass of Content and Criterion validity, contradicting the disjoint coordinate-sibling partition asserted above." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) ;
  rdfs:comment "'Criterion validity is often divided into concurrent and predictive validity based on the timing of measurement.'" .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) ;
  rdfs:comment "'Convergent and discriminant validity are the two subtypes of validity that make up construct validity.'" .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:subClassOf ea:EducationalConcept ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal .

# Classification by source of error ("four types of reliability")
ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) ;
  rdfs:comment "'There are four types of reliability: student-related ... rater-related ... test administration-related ... and test-related.'" .

# Classification by estimation method ("general classes of reliability estimates")
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ; skos:altLabel "repeatability" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ; skos:altLabel "parallel-forms reliability" .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability
                ea:InterMethodReliability ea:InternalConsistencyReliability ) ;
  rdfs:comment "'There are several general classes of reliability estimates: Inter-rater ... Test-retest ... Inter-method ... Internal consistency.'" .

#################################################################
# SCORE COMPOSITION (X = T + E)
#################################################################

ea:Score a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
