ea:ErrorScore a owl:Class ; rdfs:subClassOf ea:Score .
ea:ObservedScore a owl:Class ; rdfs:subClassOf ea:Score ;
  rdfs:comment "X = T + E: the observed score is composed of a true-score component and an error component." .

[] a owl:AllDisjointClasses ; owl:members ( ea:TrueScore ea:ErrorScore ) .

ea:hasTrueScoreComponent a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ObservedScore ; rdfs:range ea:TrueScore .
ea:hasErrorComponent a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ObservedScore ; rdfs:range ea:ErrorScore .

#################################################################
# MEASUREMENT MODELS
#################################################################

ea:MeasurementModel a owl:Class ; rdfs:subClassOf ea:EducationalConcept .
