ea:AimLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Intended learning outcome (aim)." .
ea:ObjectiveLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Measured learning outcome (objective)." .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .

[] a owl:AllDisjointClasses ;
